def climate_validate():
    i = 0
    a = 0.0
    z = 0.0
    pa = 0.0
    if (((Wind.type_ == FILE_WIND) or (Evap.type_ == FILE_EVAP)) or (Evap.type_ == TEMPERATURE_EVAP)):
        if (Fclimate.mode == NO_FILE):
            report_writeErrorMsg(ERR_NO_CLIMATE_FILE, L0)
    if (Fclimate.mode == USE_FILE):
        climate_openFile()
    if ((((Snow.tipm < 0.0) or (Snow.tipm > 1.0)) or (Snow.rnm < 0.0)) or (Snow.rnm > 1.0)):
        report_writeErrorMsg(ERR_SNOWMELT_PARAMS, L0)
    a = Temp.anglat
    if ((a <= -89.99) or (a >= 89.99)):
        report_writeErrorMsg(ERR_SNOWMELT_PARAMS, L0)
    else:
        Temp.tanAnglat = _tan(((a * 3.141592654) / 180.0))
    z = (Temp.elev / 1000.0)
    if (z <= 0.0):
        pa = 29.9
    else:
        pa = ((29.9 - (1.02 * z)) + (0.0032 * _pow(z, 2.4)))
    Temp.gamma = (0.000359 * pa)
    i = 0
    while (i < 12):
        if (UnitSystem == SI):
            Adjust.temp[i] *= (9.0 / 5.0)
        Adjust.evap[i] = _fdiv(Adjust.evap[i], UCF(EVAPRATE))
        i += 1


