def setNextEvapDate(theDate):
    yr = Box(0)
    mon = Box(0)
    day = Box(0)
    k = 0
    d = Box(0.0)
    e = Box(0.0)
    if (NextEvapDate.v > theDate):
        return
    if Evap.type_ == CONSTANT_EVAP:
        NextEvapDate.v = (theDate + 365.)
    elif Evap.type_ == MONTHLY_EVAP:
        datetime_decodeDate(theDate, yr, mon, day)
        if (mon.v == 12):
            mon.v = 1
            yr.v += 1
        else:
            mon.v += 1
        NextEvapDate.v = datetime_encodeDate(yr.v, mon.v, 1)
    elif Evap.type_ == TIMESERIES_EVAP:
        k = Evap.tSeries
        if (k >= 0):
            NextEvapDate.v = (theDate + 365.)
            while ((table_getNextEntry(Tseries[k], d, e)) and (d.v <= EndDateTime)):
                if (d.v >= theDate):
                    NextEvapDate.v = d.v
                    NextEvapRate.v = e.v
                    break
    elif Evap.type_ == FILE_EVAP:
        NextEvapDate.v = (_floor(theDate) + 1.0)
    else:
        NextEvapDate.v = (theDate + 365.)


