def setEvap(theDate):
    k = 0
    mon = datetime_monthOfYear(theDate)
    if Evap.type_ == CONSTANT_EVAP:
        Evap.rate = _fdiv(Evap.monthlyEvap[0], UCF(EVAPRATE))
    elif Evap.type_ == MONTHLY_EVAP:
        Evap.rate = _fdiv(Evap.monthlyEvap[(mon - 1)], UCF(EVAPRATE))
    elif Evap.type_ == TIMESERIES_EVAP:
        if (theDate >= NextEvapDate.v):
            Evap.rate = _fdiv(NextEvapRate.v, UCF(EVAPRATE))
    elif Evap.type_ == FILE_EVAP:
        Evap.rate = _fdiv(FileValue[EVAP], UCF(EVAPRATE))
