def convertGhcndValue(var, v):
    _ft = False
    while True:
        if _ft or var in (TMIN, TMAX):
            if FileTempUnits == DEG_C10:
                return ((((v / 10.) * 9.0) / 5.0) + 32.0)
            elif FileTempUnits == DEG_C:
                return (((v * 9.0) / 5.0) + 32.0)
            else:
                return v
            _ft = True
        if _ft or var == EVAP:
            if FileTempUnits == DEG_C10:
                v = v / 10.
                if (UnitSystem == US):
                    v = v / 25.4
                return v
            elif FileTempUnits == DEG_C:
                if (UnitSystem == US):
                    v = v / 25.4
                return v
            else:
                if (UnitSystem == SI):
                    v *= 25.4
                return v
            _ft = True
        if _ft or var == WIND:
            if FileTempUnits == DEG_C10:
                if (FileWindType == WDMV):
                    return ((v * 0.62137) / 24.)
                else:
                    return ((((v / 10.) / 1000.) * 0.62137) * 3600.)
            elif FileTempUnits == DEG_C:
                if (FileWindType == WDMV):
                    return ((v * 0.62137) / 24.)
                else:
                    return (((v / 1000.) * 0.62137) * 3600.)
            else:
                if (FileWindType == WDMV):
                    return (v / 24.)
                else:
                    return v
            _ft = True
        if _ft or var not in (TMIN, TMAX, EVAP, WIND,):
            return v
        break


