# controls.c:439
def controls_addRuleClause(r, keyword, tok, nToks):
    global InputState
    if keyword == r_RULE:
        if (Rules[r].ID == (None)):
            Rules[r].ID = project_findID(CONTROL, tok[1])
        InputState = r_RULE
        if (nToks > 2):
            return ERR_RULE
        return 0
    elif keyword == r_IF:
        if (InputState != r_RULE):
            return ERR_RULE
        InputState = r_IF
        return addPremise(r, r_AND, tok, nToks)
    elif keyword == r_AND:
        if (InputState == r_IF):
            return addPremise(r, r_AND, tok, nToks)
        elif ((InputState == r_THEN) or (InputState == r_ELSE)):
            return addAction(r, tok, nToks)
        else:
            return ERR_RULE
    elif keyword == r_OR:
        if (InputState != r_IF):
            return ERR_RULE
        return addPremise(r, r_OR, tok, nToks)
    elif keyword == r_THEN:
        if (InputState != r_IF):
            return ERR_RULE
        InputState = r_THEN
        return addAction(r, tok, nToks)
    elif keyword == r_ELSE:
        if (InputState != r_THEN):
            return ERR_RULE
        InputState = r_ELSE
        return addAction(r, tok, nToks)
    elif keyword == r_PRIORITY:
        if ((InputState != r_THEN) and (InputState != r_ELSE)):
            return ERR_RULE
        InputState = r_PRIORITY
        if (not (getDouble(tok[1], FieldRef(Rules[r], 'priority')))):
            return ERR_NUMBER
        if (nToks > 2):
            return ERR_RULE
        return 0
    return 0


# controls.c:495
def controls_evaluate(currentTime, elapsedTime, tStep):
    global CurrentDate, CurrentTime, ElapsedTime
    r = 0
    result = 0
    p = None
    a = None
    CurrentDate = _floor(currentTime)
    CurrentTime = (currentTime - _floor(currentTime))
    ElapsedTime = elapsedTime
    if (RuleCount == 0):
        return 0
    clearActionList()
    r = 0
    while (r < RuleCount):
        result = 1
        p = Rules[r].firstPremise
        while (p is not None):
            if (p.type_ == r_OR):
                if (result == 0):
                    result = evaluatePremise(p, tStep)
            else:
                if (result == 0):
                    break
                result = evaluatePremise(p, tStep)
            p = p.next_
        if (result == 1):
            a = Rules[r].thenActions
        else:
            a = Rules[r].elseActions
        while (a is not None):
            updateActionValue(a, currentTime, tStep)
            updateActionList(a)
            a = a.next_
        r += 1
    if (ActionList is not None):
        return executeActionList(currentTime)
    else:
        return 0


