# controls.c:824
def getPremiseValue(token, attrib, value):
    strDate = CPtr.buf(25)
    if attrib == r_STATUS:
        value.v = findmatch(token, StatusWords)
        if (value.v < 0.0):
            value.v = findmatch(token, ConduitWords)
        if (value.v < 0.0):
            return error_setInpError(ERR_KEYWORD, token)
    elif attrib in (r_TIME, r_CLOCKTIME, r_TIMEOPEN, r_TIMECLOSED):
        if (not (datetime_strToTime(token, value))):
            return error_setInpError(ERR_DATETIME, token)
    elif attrib == r_DATE:
        if (not (datetime_strToDate(token, value))):
            return error_setInpError(ERR_DATETIME, token)
    elif attrib == r_DAY:
        if (not (getDouble(token, value))):
            return error_setInpError(ERR_NUMBER, token)
        if ((value.v < 1.0) or (value.v > 7.0)):
            return error_setInpError(ERR_DATETIME, token)
    elif attrib == r_MONTH:
        if (not (getDouble(token, value))):
            return error_setInpError(ERR_NUMBER, token)
        if ((value.v < 1.0) or (value.v > 12.0)):
            return error_setInpError(ERR_DATETIME, token)
    elif attrib == r_DAYOFYEAR:
        sstrncpy(strDate, token, (6 & 0xFFFFFFFFFFFFFFFF))
        sstrcat(strDate, L35, (25 & 0xFFFFFFFFFFFFFFFF))
        if datetime_strToDate(strDate, value):
            value.v = datetime_dayOfYear(value.v)
        elif (((not (getDouble(token, value))) or (value.v < 1)) or (value.v > 365)):
            return error_setInpError(ERR_DATETIME, token)
    else:
        if (not (getDouble(token, value))):
            return error_setInpError(ERR_NUMBER, token)
    return 0


