def setActionSetting(tok, nToks, curve, tseries, attrib, values):
    k = 0
    m = 0
    if (nToks < 6):
        return error_setInpError(ERR_ITEMS, L0)
    k = findmatch(tok[5], SettingTypeWords)
    if ((k >= 0) and (nToks < 7)):
        return error_setInpError(ERR_ITEMS, L0)
    if k == r_CURVE:
        m = project_findObject(CURVE, tok[6])
        if (m < 0):
            return error_setInpError(ERR_NAME, tok[6])
        curve.v = m
    elif k == r_TIMESERIES:
        m = project_findObject(TSERIES, tok[6])
        if (m < 0):
            return error_setInpError(ERR_NAME, tok[6])
        tseries.v = m
        Tseries[m].refersTo = CONTROL
    elif k == r_PID:
        if (nToks < 9):
            return error_setInpError(ERR_ITEMS, L0)
        m = 6
        while (m <= 8):
            if (not (getDouble(tok[m], ElemRef(values, (m - 6))))):
                return error_setInpError(ERR_NUMBER, tok[m])
            m += 1
        attrib.v = r_PID
    else:
        if (not (getDouble(tok[5], ElemRef(values, 0)))):
            return error_setInpError(ERR_NUMBER, tok[5])
    return 0


