# controls.c:1111
def getPIDSetting(a, dt):
    e0 = 0.0
    setting = 0.0
    p = 0.0
    i = 0.0
    d = 0.0
    update = 0.0
    tolerance = 0.0001
    dt *= 1440.0
    e0 = (SetPoint - ControlValue)
    if (math.fabs(e0) > 1e-06):
        if (SetPoint != 0.0):
            e0 = _fdiv(e0, SetPoint)
        else:
            e0 = _fdiv(e0, ControlValue)
    if (math.fabs((e0 - a.e1)) < tolerance):
        a.e2 = 0.0
        a.e1 = 0.0
    p = ((e0 - a.e1))
    if (a.ki == 0.0):
        i = 0.0
    else:
        i = _fdiv((e0 * dt), a.ki)
    d = _fdiv((a.kd * (((e0 - (2.0 * a.e1)) + a.e2))), dt)
    update = (a.kp * (((p + i) + d)))
    if (math.fabs(update) < tolerance):
        update = 0.0
    setting = (Link[a.link].targetSetting + update)
    a.e2 = a.e1
    a.e1 = e0
    if (setting < 0.0):
        setting = 0.0
    if ((Link[a.link].type_ != PUMP) and (setting > 1.0)):
        setting = 1.0
    return setting


