def evaluatePremise(p, tStep):
    global ControlValue
    lhsValue = 0.0
    rhsValue = 0.0
    result = 0
    if (p.exprIndex >= 0):
        lhsValue = mathexpr_eval(Expression[p.exprIndex].expression, getNamedVariableValue)
    else:
        lhsValue = getVariableValue(p.lhsVar)
    if (p.value == -10000000000.0):
        rhsValue = getVariableValue(p.rhsVar)
    else:
        rhsValue = p.value
    if ((lhsValue == -10000000000.0) or (rhsValue == -10000000000.0)):
        return 0
    if p.lhsVar.attribute in (r_TIME, r_CLOCKTIME):
        return compareTimes(lhsValue, p.relation, rhsValue, (tStep / 2.0))
    elif p.lhsVar.attribute in (r_TIMEOPEN, r_TIMECLOSED):
        result = compareTimes(lhsValue, p.relation, rhsValue, (tStep / 2.0))
        ControlValue = (lhsValue * 24.0)
        return result
    else:
        return compareValues(lhsValue, p.relation, rhsValue)


