# controls.c:1405
def compareTimes(lhsValue, relation, rhsValue, halfStep):
    if (relation == EQ):
        if ((lhsValue >= (rhsValue - halfStep)) and (lhsValue < (rhsValue + halfStep))):
            return 1
        return 0
    elif (relation == NE):
        if ((lhsValue < (rhsValue - halfStep)) or (lhsValue >= (rhsValue + halfStep))):
            return 1
        return 0
    else:
        return compareValues(lhsValue, relation, rhsValue)


# controls.c:1432
def compareValues(lhsValue, relation, rhsValue):
    global ControlValue, SetPoint
    SetPoint = rhsValue
    ControlValue = lhsValue
    if relation == EQ:
        if (lhsValue == rhsValue):
            return 1
    elif relation == NE:
        if (lhsValue != rhsValue):
            return 1
    elif relation == LT:
        if (lhsValue < rhsValue):
            return 1
    elif relation == LE:
        if (lhsValue <= rhsValue):
            return 1
    elif relation == GT:
        if (lhsValue > rhsValue):
            return 1
    elif relation == GE:
        if (lhsValue >= rhsValue):
            return 1
    return 0


