def findroot_Newton(x1, x2, rts, xacc, func, p):
    j = 0
    n = 0
    df = Box(0.0)
    dx = 0.0
    dxold = 0.0
    f = Box(0.0)
    x = 0.0
    temp = 0.0
    xhi = 0.0
    xlo = 0.0
    x = rts.v
    xlo = x1
    xhi = x2
    dxold = math.fabs((x2 - x1))
    dx = dxold
    func(x, f, df, p)
    n += 1
    j = 1
    while (j <= 60):
        if (((((((((x - xhi)) * df.v) - f.v)) * (((((x - xlo)) * df.v) - f.v))) >= 0.0) or ((math.fabs((2.0 * f.v)) > math.fabs((dxold * df.v)))))):
            dxold = dx
            dx = (0.5 * ((xhi - xlo)))
            x = (xlo + dx)
            if (xlo == x):
                break
        else:
            dxold = dx
            dx = _fdiv(f.v, df.v)
            temp = x
            x -= dx
            if (temp == x):
                break
        if (math.fabs(dx) < xacc):
            break
        func(x, f, df, p)
        n += 1
        if (f.v < 0.0):
            xlo = x
        else:
            xhi = x
        j += 1
    rts.v = x
    if (n <= 60):
        return n
    else:
        return 0


