def findroot_Ridder(x1, x2, xacc, func, p):
    j = 0
    ans = 0.0
    fhi = 0.0
    flo = 0.0
    fm = 0.0
    fnew = 0.0
    s = 0.0
    xhi = 0.0
    xlo = 0.0
    xm = 0.0
    xnew = 0.0
    flo = func(x1, p)
    fhi = func(x2, p)
    if (flo == 0.0):
        return x1
    if (fhi == 0.0):
        return x2
    ans = (0.5 * ((x1 + x2)))
    if ((((flo > 0.0) and (fhi < 0.0))) or (((flo < 0.0) and (fhi > 0.0)))):
        xlo = x1
        xhi = x2
        j = 1
        while (j <= 60):
            xm = (0.5 * ((xlo + xhi)))
            fm = func(xm, p)
            s = _sqrt(((fm * fm) - (flo * fhi)))
            if (s == 0.0):
                return ans
            xnew = (xm + (((xm - xlo)) * (_fdiv((((1.0 if (flo >= fhi) else -1.0)) * fm), s))))
            if (math.fabs((xnew - ans)) <= xacc):
                break
            ans = xnew
            fnew = func(ans, p)
            if (((math.fabs(fm) if ((fnew) >= 0.0) else -(math.fabs(fm)))) != fm):
                xlo = xm
                flo = fm
                xhi = ans
                fhi = fnew
            elif (((math.fabs(flo) if ((fnew) >= 0.0) else -(math.fabs(flo)))) != flo):
                xhi = ans
                fhi = fnew
            elif (((math.fabs(fhi) if ((fnew) >= 0.0) else -(math.fabs(fhi)))) != fhi):
                xlo = ans
                flo = fnew
            else:
                return ans
            if (math.fabs((xhi - xlo)) <= xacc):
                return ans
            j += 1
        return ans
    return -1.e20


