def gage_updatePastRain(j, tStep):
    i = 0
    t = 0
    r = 0.0
    r = (Gage[j].rainfall / 3600.)
    while (tStep > 0):
        t = (3600 - Gage[j].pastInterval)
        if (tStep > t):
            Gage[j].pastRain[0] += (t * r)
            i = 48
            while (i > 0):
                Gage[j].pastRain[i] = Gage[j].pastRain[(i - 1)]
                i -= 1
            Gage[j].pastInterval = 0
            Gage[j].pastRain[0] = 0.0
