# gage.c:674
def convertRainfall(j, r):
    r1 = 0.0
    _sw1 = Gage[j].rainType
    if _sw1 == RAINFALL_INTENSITY:
        r1 = r
    elif _sw1 == RAINFALL_VOLUME:
        r1 = (_fdiv(r, Gage[j].rainInterval) * 3600.0)
    elif _sw1 == CUMULATIVE_RAINFALL:
        if (r < Gage[j].rainAccum):
            r1 = (_fdiv(r, Gage[j].rainInterval) * 3600.0)
        else:
            r1 = (_fdiv(((r - Gage[j].rainAccum)), Gage[j].rainInterval) * 3600.0)
        Gage[j].rainAccum = r
    else:
        r1 = r
    return ((r1 * Gage[j].unitsFactor) * Adjust.rainFactor)


