# inflow.c:456
def getPatternFactor(p, month, day, hour):
    _sw1 = Pattern[p].type_
    if _sw1 == MONTHLY_PATTERN:
        if ((month >= 0) and (month < 12)):
            return Pattern[p].factor[month]
    elif _sw1 == DAILY_PATTERN:
        if ((day >= 0) and (day < 7)):
            return Pattern[p].factor[day]
    elif _sw1 == HOURLY_PATTERN:
        if ((hour >= 0) and (hour < 24)):
            return Pattern[p].factor[hour]
    elif _sw1 == WEEKEND_PATTERN:
        if ((day == 0) or (day == 6)):
            if ((hour >= 0) and (hour < 24)):
                return Pattern[p].factor[hour]
    return 1.0


