    i = 0
    while (i < 5):
        Mlinks[i] = 0
        i += 1
    Mevents = 0
    i = 0
    while (i < Nobjects[TSERIES]):
        Tseries[i].lastDate = (StartDate.v + StartTime.v)
        i += 1
    sect = 0
    errsum = 0
    rt.rewind(Finp.file)
    while (rt.fgets(line, 1024, Finp.file) != (None)):
        lineCount += 1
        sstrncpy(wLine, line, (1024 & 0xFFFFFFFFFFFFFFFF))
        Ntokens = getTokens(wLine)
        if (Ntokens == 0):
            continue
        if (Tok[0][0] == 59):
            continue
        lineLength = _i32(rt.strlen(line))
        if (lineLength >= 1024):
            comment = rt.strchr(line, 59)
            if (comment is not None):
                lineLength = _i32((CPtr.diff(comment, line)))
            if (lineLength >= 1024):
                inperr = ERR_LINE_LENGTH
                report_writeInputErrorMsg(inperr, sect, line, lineCount)
                errsum += 1
        if (Tok[0][0] == 91):
            newsect = findmatch(Tok[0], SectWords)
            if (newsect >= 0):
                if (sect == s_TRANSECT):
                    transect_validate((Nobjects[TRANSECT] - 1))
                sect = newsect
                continue
            else:
                inperr = error_setInpError(ERR_KEYWORD, Tok[0])
                report_writeInputErrorMsg(inperr, sect, line, lineCount)
                errsum += 1
                break
        else:
            inperr = parseLine(sect, line)
            if (inperr > 0):
                errsum += 1
                if (errsum > MAXERRS):
                    report_writeLine(L201)
                else:
                    report_writeInputErrorMsg(inperr, sect, line, lineCount)
        if (errsum > MAXERRS):
            break
    if (errsum > 0):
        ErrorCode = ERR_INPUT
    return ErrorCode


