def findmatch(s, keyword):
    i = 0
    while (keyword[i] != (None)):
        if match(s, keyword[i]):
            return (i)
        i += 1
    return (-1)


# input.c:798
def match(str_, substr):
    i = 0
    j = 0
    k = 0
    if (not substr[0]):
        return (0)
    k = 0
    while str_[k]:
        if (str_[k] != 32):
            break
        k += 1
    i = k; j = 0
    while substr[j]:
        if ((not str_[i]) or ((((((str_[i]) & ~32)) if ((((str_[i]) >= 97) and ((str_[i]) <= 122))) else (str_[i]))) != (((((substr[j]) & ~32)) if ((((substr[j]) >= 97) and ((substr[j]) <= 122))) else (substr[j]))))):
            return (0)
        i += 1
        j += 1
    return (1)


