def getInt(s, y):
    x = Box(0.0)
    if getDouble(s, x):
        if (x.v < 0.0):
            x.v -= 0.01
        else:
            x.v += 0.01
        y.v = D2I(x.v)
        return 1
    y.v = 0
    return 0


