# kinwave.c:57
def kinwave_execute(j, qinflow, qoutflow, tStep):
    global Afull, Beta1, C1, C2, Qfull, pXsect
    k = 0
    result = 1
    dxdt = 0.0
    dq = 0.0
    ain = 0.0
    aout = Box(0.0)
    qin = 0.0
    qout = 0.0
    a1 = 0.0
    a2 = 0.0
    q1 = 0.0
    q2 = 0.0
    q3 = 0.0
    qoutflow.v = (qinflow.v)
    if (Link[j].type_ != CONDUIT):
        return result
    if (Link[j].xsect.type_ == DUMMY):
        return result
    pXsect = Link[j].xsect
    Qfull = Link[j].qFull
    Afull = Link[j].xsect.aFull
    k = Link[j].subIndex
    Beta1 = _fdiv(Conduit[k].beta, Qfull)
    q1 = _fdiv(Conduit[k].q1, Qfull)
    q2 = _fdiv(Conduit[k].q2, Qfull)
    qin = _fdiv(_fdiv((qinflow.v), Conduit[k].barrels), Qfull)
    q3 = _fdiv(link_getLossRate(j, KW, (qin * Qfull), tStep), Qfull)
    a1 = _fdiv(Conduit[k].a1, Afull)
    a2 = _fdiv(Conduit[k].a2, Afull)
    if (qin >= 1.0):
        ain = 1.0
    else:
        ain = _fdiv(xsect_getAofS(pXsect, _fdiv(qin, Beta1)), Afull)
    if ((qin <= 1e-06) and (q2 <= 1e-06)):
        qout = 0.0
        aout.v = 0.0
    else:
        dxdt = _fdiv((_fdiv(link_getLength(j), tStep) * Afull), Qfull)
        dq = (q2 - q1)
        C1 = ((dxdt * WT) / WX)
        C2 = (((1.0 - WT)) * ((ain - a1)))
        C2 = (C2 - (WT * a2))
        C2 = ((C2 * dxdt) / WX)
        C2 = ((C2 + ((((1.0 - WX)) / WX) * dq)) - qin)
        C2 = (C2 + (q3 / WX))
        aout.v = a2
        result = solveContinuity(qin, ain, aout)
        if (result == -1):
            report_writeErrorMsg(ERR_KINWAVE, Link[j].ID)
            return 1
        if (result <= 0):
            result = 1
        qout = (Beta1 * xsect_getSofA(pXsect, (aout.v * Afull)))
        if (qin > 1.0):
            qin = 1.0
    Conduit[k].q1 = (qin * Qfull)
    Conduit[k].a1 = (ain * Afull)
    Conduit[k].q2 = (qout * Qfull)
    Conduit[k].a2 = (aout.v * Afull)
    Conduit[k].fullState = link_getFullState(Conduit[k].a1, Conduit[k].a2, Afull)
    qinflow.v = (Conduit[k].q1 * Conduit[k].barrels)
    qoutflow.v = (Conduit[k].q2 * Conduit[k].barrels)
    return result


# kinwave.c:170
def solveContinuity(qin, ain, aout):
    n = 0
    aLo = 0.0
    aHi = 0.0
    aTmp = 0.0
    fLo = 0.0
    fHi = 0.0
    tol = EPSIL
    aHi = 1.0
    fHi = ((1.0 + C1) + C2)
    aLo = _fdiv(xsect_getAmax(pXsect), Afull)
    if (aLo < aHi):
        fLo = ((((Beta1 * pXsect.sMax)) + ((C1 * aLo))) + C2)
    else:
        fLo = fHi
    if ((fHi * fLo) > 0.0):
        aHi = aLo
        fHi = fLo
        aLo = 0.0
        fLo = C2
    if ((fHi * fLo) <= 0.0):
        if ((aout.v < aLo) or (aout.v > aHi)):
            aout.v = (0.5 * ((aLo + aHi)))
        if (fLo > fHi):
            aTmp = aLo
            aLo = aHi
            aHi = aTmp
        n = findroot_Newton(aLo, aHi, aout, tol, evalContinuity, (None))
        if (n <= 0):
            n = -1
    elif (fLo < 0.0):
        if (qin > 1.0):
            aout.v = ain
        else:
            aout.v = 1.0
        n = -2
    elif (fLo > 0):
        aout.v = 0.0
        n = -3
    else:
        n = -1
    return n


# kinwave.c:261
def evalContinuity(a, f, df, p):
    f.v = ((((Beta1 * xsect_getSofA(pXsect, (a * Afull)))) + ((C1 * a))) + C2)
    df.v = ((((Beta1 * Afull) * xsect_getdSdA(pXsect, (a * Afull)))) + C1)


