def landuse_getInitBuildup(landFactor, initBuildup, area, curb):
    i = 0
    p = 0
    startDrySeconds = 0.0
    f = 0.0
    fArea = 0.0
    fCurb = 0.0
    buildup = 0.0
    startDrySeconds = (StartDryDays * 86400)
    i = 0
    while (i < Nobjects[LANDUSE]):
        landFactor[i].lastSwept = (StartDateTime - Landuse[i].sweepDays0)
        f = landFactor[i].fraction
        fArea = ((f * area) * UCF(LANDAREA))
        fCurb = (f * curb)
        p = 0
        while (p < Nobjects[POLLUT]):
            buildup = 0.0
            if (initBuildup[p] > 0.0):
                buildup = (initBuildup[p] * fArea)
            else:
                buildup = landuse_getBuildup(i, p, fArea, fCurb, buildup, startDrySeconds)
            landFactor[i].buildup[p] = buildup
            p += 1
        i += 1


# landuse.c:411
def landuse_getBuildup(i, p, area, curb, buildup, tStep):
    n = 0
    days = 0.0
    perUnit = 0.0
    if ((Landuse[i].buildupFunc[p].funcType == NO_BUILDUP) or (tStep == 0.0)):
        return buildup
    n = Landuse[i].buildupFunc[p].normalizer
    perUnit = 1.0
    if (n == PER_AREA):
        perUnit = area
    if (n == PER_CURB):
        perUnit = curb
    if (perUnit == 0.0):
        return 0.0
    if (Landuse[i].buildupFunc[p].funcType == EXTERNAL_BUILDUP):
        return (landuse_getExternalBuildup(i, p, _fdiv(buildup, perUnit), tStep) * perUnit)
    days = landuse_getBuildupDays(i, p, _fdiv(buildup, perUnit))
    days += (tStep / 86400)
    return (landuse_getBuildupMass(i, p, days) * perUnit)


# landuse.c:458
def landuse_getBuildupDays(i, p, buildup):
    c0 = Landuse[i].buildupFunc[p].coeff[0]
    c1 = Landuse[i].buildupFunc[p].coeff[1]
    c2 = Landuse[i].buildupFunc[p].coeff[2]
    if (buildup == 0.0):
        return 0.0
    if (buildup >= c0):
        return Landuse[i].buildupFunc[p].maxDays
    _sw1 = Landuse[i].buildupFunc[p].funcType
    if _sw1 == POWER_BUILDUP:
        if ((c1 * c2) == 0.0):
            return 0.0
        else:
            return _pow((_fdiv(buildup, c1)), (_fdiv(1.0, c2)))
    elif _sw1 == EXPON_BUILDUP:
        if ((c0 * c1) == 0.0):
            return 0.0
        else:
            return _fdiv(-(_log((1. - _fdiv(buildup, c0)))), c1)
    elif _sw1 == SATUR_BUILDUP:
        if (c0 == 0.0):
            return 0.0
        else:
            return _fdiv((buildup * c2), ((c0 - buildup)))
    else:
        return 0.0


# landuse.c:494
def landuse_getBuildupMass(i, p, days):
    b = 0.0
    c0 = Landuse[i].buildupFunc[p].coeff[0]
    c1 = Landuse[i].buildupFunc[p].coeff[1]
    c2 = Landuse[i].buildupFunc[p].coeff[2]
    if (days == 0.0):
        return 0.0
    if (days >= Landuse[i].buildupFunc[p].maxDays):
        return c0
    _sw1 = Landuse[i].buildupFunc[p].funcType
    if _sw1 == POWER_BUILDUP:
        b = (c1 * _pow(days, c2))
        if (b > c0):
            b = c0
    elif _sw1 == EXPON_BUILDUP:
        b = (c0 * ((1.0 - _exp((-days * c1)))))
    elif _sw1 == SATUR_BUILDUP:
        b = _fdiv((days * c0), ((c2 + days)))
    else:
        b = 0.0
    return b


