def landuse_getWashoffLoad(i, p, area, landFactor, runoff, vOutflow):
    landuseArea = 0.0
    buildup = 0.0
    washoffQual = 0.0
    washoffLoad = 0.0
    bmpRemoval = 0.0
    buildup = landFactor[i].buildup[p]
    landuseArea = (landFactor[i].fraction * area)
    washoffQual = landuse_getWashoffQual(i, p, buildup, runoff, landuseArea)
    washoffLoad = (_fdiv(((washoffQual * vOutflow) * landuseArea), area) * Pollut[p].mcf)
    if ((Landuse[i].buildupFunc[p].funcType != NO_BUILDUP) or (buildup > washoffLoad)):
        washoffLoad = (((washoffLoad) if (((washoffLoad) <= (buildup))) else (buildup)))
        buildup -= washoffLoad
        landFactor[i].buildup[p] = buildup
    else:
        massbal_updateLoadingTotals(BUILDUP_LOAD, p, washoffLoad)
        landFactor[i].buildup[p] = 0.0
    bmpRemoval = (Landuse[i].washoffFunc[p].bmpEffic * washoffLoad)
    if (bmpRemoval > 0.0):
        massbal_updateLoadingTotals(BMP_REMOVAL_LOAD, p, bmpRemoval)
        washoffLoad -= bmpRemoval
    return _fdiv(washoffLoad, Pollut[p].mcf)


# landuse.c:612
def landuse_getWashoffQual(i, p, buildup, runoff, area):
    cWashoff = 0.0
    coeff = Landuse[i].washoffFunc[p].coeff
    expon = Landuse[i].washoffFunc[p].expon
    func = Landuse[i].washoffFunc[p].funcType
    if ((func == NO_WASHOFF) or (runoff == 0.0)):
        return 0.0
    if ((Landuse[i].buildupFunc[p].funcType != NO_BUILDUP) and (buildup == 0.0)):
        return 0.0
    if (func == EXPON_WASHOFF):
        cWashoff = _fdiv(((coeff * _pow((runoff * UCF(RAINFALL)), expon)) * buildup), Pollut[p].mcf)
        cWashoff = _fdiv(cWashoff, (runoff * area))
    elif (func == RATING_WASHOFF):
        cWashoff = (coeff * _pow((runoff * area), (expon - 1.0)))
    elif (func == EMC_WASHOFF):
        cWashoff = coeff
    return cWashoff


