def landuse_getExternalBuildup(i, p, buildup, tStep):
    maxBuildup = Landuse[i].buildupFunc[p].coeff[0]
    sf = Landuse[i].buildupFunc[p].coeff[1]
    ts = D2I(_floor(Landuse[i].buildupFunc[p].coeff[2]))
    rate = 0.0
    if (NewRunoffTime == 0.0):
        return 0.0
    if (ts >= 0):
        rate = (sf * table_tseriesLookup(Tseries[ts], getDateTime(NewRunoffTime), 0))
    buildup = (buildup + ((rate * tStep) / 86400))
    buildup = (((buildup) if (((buildup) <= (maxBuildup))) else (maxBuildup)))
    return buildup


