# lid.c:932
def validateLidProc(j):
    layerMissing = 0
    if (LidProcs[j].lidType < 0):
        report_writeErrorMsg(ERR_LID_TYPE, LidProcs[j].ID)
        return
    _sw1 = LidProcs[j].lidType
    if _sw1 in (BIO_CELL, RAIN_GARDEN):
        if (LidProcs[j].soil.thickness <= 0.0):
            layerMissing = 1
    elif _sw1 == GREEN_ROOF:
        if (LidProcs[j].soil.thickness <= 0.0):
            layerMissing = 1
        if (LidProcs[j].drainMat.thickness <= 0.0):
            layerMissing = 1
    elif _sw1 == POROUS_PAVEMENT:
        if (LidProcs[j].pavement.thickness <= 0.0):
            layerMissing = 1
    elif _sw1 == INFIL_TRENCH:
        if (LidProcs[j].storage.thickness <= 0.0):
            layerMissing = 1
    if layerMissing:
        report_writeErrorMsg(ERR_LID_LAYER, LidProcs[j].ID)
        return
    if (LidProcs[j].lidType == POROUS_PAVEMENT):
        if (((((LidProcs[j].pavement.thickness <= 0.0) or (LidProcs[j].pavement.kSat <= 0.0)) or (LidProcs[j].pavement.voidFrac <= 0.0)) or (LidProcs[j].pavement.voidFrac > 1.0)) or (LidProcs[j].pavement.impervFrac > 1.0)):
            sstrncpy(Msg, LidProcs[j].ID, (1024 & 0xFFFFFFFFFFFFFFFF))
            sstrcat(Msg, L284, (1024 & 0xFFFFFFFFFFFFFFFF))
            report_writeErrorMsg(ERR_LID_PARAMS, Msg)
    if (LidProcs[j].soil.thickness > 0.0):
        if (((((LidProcs[j].soil.porosity <= 0.0) or (LidProcs[j].soil.fieldCap >= LidProcs[j].soil.porosity)) or (LidProcs[j].soil.wiltPoint >= LidProcs[j].soil.fieldCap)) or (LidProcs[j].soil.kSat <= 0.0)) or (LidProcs[j].soil.kSlope < 0.0)):
            sstrncpy(Msg, LidProcs[j].ID, (1024 & 0xFFFFFFFFFFFFFFFF))
            sstrcat(Msg, L285, (1024 & 0xFFFFFFFFFFFFFFFF))
            report_writeErrorMsg(ERR_LID_PARAMS, Msg)
    if (LidProcs[j].storage.thickness > 0.0):
        if ((LidProcs[j].storage.voidFrac <= 0.0) or (LidProcs[j].storage.voidFrac > 1.0)):
            sstrncpy(Msg, LidProcs[j].ID, (1024 & 0xFFFFFFFFFFFFFFFF))
            sstrcat(Msg, L286, (1024 & 0xFFFFFFFFFFFFFFFF))
            report_writeErrorMsg(ERR_LID_PARAMS, Msg)
    else:
        LidProcs[j].storage.voidFrac = 1.0
        LidProcs[j].drain.offset = 0.0
    if ((LidProcs[j].drain.hOpen > 0.0) and (LidProcs[j].drain.hOpen <= LidProcs[j].drain.hClose)):
        sstrncpy(Msg, LidProcs[j].ID, (1024 & 0xFFFFFFFFFFFFFFFF))
        sstrcat(Msg, L287, (1024 & 0xFFFFFFFFFFFFFFFF))
        report_writeErrorMsg(ERR_LID_PARAMS, Msg)
    if (LidProcs[j].lidType == VEG_SWALE):
        if (((LidProcs[j].surface.roughness * LidProcs[j].surface.surfSlope) <= 0.0) or (LidProcs[j].surface.thickness == 0.0)):
            sstrncpy(Msg, LidProcs[j].ID, (1024 & 0xFFFFFFFFFFFFFFFF))
            sstrcat(Msg, L288, (1024 & 0xFFFFFFFFFFFFFFFF))
            report_writeErrorMsg(ERR_LID_PARAMS, Msg)
        else:
            LidProcs[j].surface.alpha = _fdiv((1.49 * _sqrt(LidProcs[j].surface.surfSlope)), LidProcs[j].surface.roughness)
    else:
        if (LidProcs[j].surface.roughness > 0.0):
            LidProcs[j].surface.alpha = (_fdiv(1.49, LidProcs[j].surface.roughness) * _sqrt(LidProcs[j].surface.surfSlope))
