def evalLidUnit(j, lidUnit, lidArea, lidInflow, tStep, qRunoff, qDrain, qReturn):
    global Vevap, VlidInfil, Vpevap
    lidProc = None
    lidRunoff = 0.0
    lidEvap = Box(0.0)
    lidInfil = Box(0.0)
    lidDrain = Box(0.0)
    lidProc = LidProcs[lidUnit.lidIndex]
    lidEvap.v = 0.0
    lidInfil.v = 0.0
    lidRunoff = (lidproc_getOutflow(lidUnit, lidProc, lidInflow, lid_EvapRate, NativeInfil, lid_MaxNativeInfil, tStep, lidEvap, lidInfil, lidDrain) * lidArea)
    lidDrain.v *= lidArea
    if (lidUnit.toPerv and (Subcatch[j].area > Subcatch[j].lidArea)):
        qReturn.v += lidRunoff
        lidRunoff = 0.0
        if ((lidUnit.drainNode == Subcatch[j].outNode) and (lidUnit.drainSubcatch == Subcatch[j].outSubcatch)):
            qReturn.v += lidDrain.v
            lidDrain.v = 0.0
    if (lidUnit.drainNode >= 0):
        massbal_updateRunoffTotals(RUNOFF_DRAINS, (lidDrain.v * tStep))
    lidUnit.newDrainFlow = lidDrain.v
    Vevap += ((lidEvap.v * tStep) * lidArea)
    VlidInfil += ((lidInfil.v * tStep) * lidArea)
    if isLidPervious(lidUnit.lidIndex):
        Vpevap += ((lidEvap.v * tStep) * lidArea)
    if (Subcatch[j].rainfall > 2.31481e-08):
        lidUnit.dryTime = 0.0
    else:
        lidUnit.dryTime += tStep
    lidproc_saveResults(lidUnit, UCF(RAINFALL), UCF(RAINDEPTH))
    qRunoff.v += lidRunoff
    qDrain.v += lidDrain.v


