def link_readXsectParams(tok, ntoks):
    i = 0
    j = 0
    k = 0
    x = [0.0] * 4
    if (ntoks < 3):
        return error_setInpError(ERR_ITEMS, L0)
    j = project_findObject(LINK, tok[0])
    if (j < 0):
        return error_setInpError(ERR_NAME, tok[0])
    k = findmatch(tok[1], XsectTypeWords)
    if (k < 0):
        return error_setInpError(ERR_KEYWORD, tok[1])
    if (Link[j].type_ == CONDUIT):
        Conduit[Link[j].subIndex].barrels = 1
    Link[j].xsect.culvertCode = 0
    if (k == IRREGULAR):
        i = project_findObject(TRANSECT, tok[2])
        if (i < 0):
            return error_setInpError(ERR_NAME, tok[2])
        Link[j].xsect.type_ = k
        Link[j].xsect.transect = i
        return 0
    elif (k == STREET_XSECT):
        i = project_findObject(STREET, tok[2])
        if (i < 0):
            return error_setInpError(ERR_NAME, tok[2])
        Link[j].xsect.type_ = k
        Link[j].xsect.transect = i
        return 0
    else:
        if (ntoks < 6):
            return error_setInpError(ERR_ITEMS, L0)
        if (k == CUSTOM):
            if ((not (getDouble(tok[2], ElemRef(x, 0)))) or (x[0] <= 0.0)):
                return error_setInpError(ERR_NUMBER, tok[2])
            i = project_findObject(CURVE, tok[3])
            if (i < 0):
                return error_setInpError(ERR_NAME, tok[3])
            Link[j].xsect.type_ = k
            Link[j].xsect.transect = i
            Link[j].xsect.yFull = _fdiv(x[0], UCF(LENGTH))
        else:
            i = 2
            while (i <= 5):
                if (not (getDouble(tok[i], ElemRef(x, (i - 2))))):
                    return error_setInpError(ERR_NUMBER, tok[i])
                i += 1
        if ((Link[j].type_ != CONDUIT) and (k == RECT_OPEN)):
            x[2] = 0.0
            x[3] = 0.0
        if (not (xsect_setParams(Link[j].xsect, k, x, UCF(LENGTH)))):
            return error_setInpError(ERR_NUMBER, L0)
        if ((Link[j].type_ == CONDUIT) and (ntoks >= 7)):
            i = rt.atoi(tok[6])
            if (i <= 0):
                return error_setInpError(ERR_NUMBER, tok[6])
            else:
                Conduit[Link[j].subIndex].barrels = i
        if ((Link[j].type_ == CONDUIT) and (ntoks >= 8)):
            i = rt.atoi(tok[7])
            if (i < 0):
                return error_setInpError(ERR_NUMBER, tok[7])
            else:
                Link[j].xsect.culvertCode = i
    return 0


