    lengthFactor = 1.0
    if (((RouteModel == DW) and (LengtheningStep > 0.0)) and (Link[j].xsect.type_ != DUMMY)):
        lengthFactor = conduit_getLengthFactor(j, k, roughness)
    if (lengthFactor != 1.0):
        Conduit[k].modLength = (lengthFactor * conduit_getLength(j))
        slope = _fdiv(slope, lengthFactor)
