    if ((RouteModel == DW) and (Link[j].xsect.type_ == FORCE_MAIN)):
        Link[j].xsect.sBot = forcemain_getRoughFactor(j, lengthFactor)
    Conduit[k].roughFactor = (32.2 * ((((roughness / 1.486)) * ((roughness / 1.486)))))
    if (Link[j].xsect.type_ == DUMMY):
        Conduit[k].beta = 0.0
    else:
        Conduit[k].beta = _fdiv((1.486 * _sqrt(math.fabs(slope))), roughness)
    Link[j].qFull = (Link[j].xsect.sFull * Conduit[k].beta)
    Conduit[k].qMax = (Link[j].xsect.sMax * Conduit[k].beta)
    aa = ((_fdiv(Conduit[k].beta, _sqrt(32.2)) * _pow(Link[j].xsect.yFull, 0.1666667)) * 0.3)
