def conduit_getSlope(j):
    elev1 = 0.0
    elev2 = 0.0
    delta = 0.0
    slope = 0.0
    length = conduit_getLength(j)
    elev1 = (Link[j].offset1 + Node[Link[j].node1].invertElev)
    elev2 = (Link[j].offset2 + Node[Link[j].node2].invertElev)
    delta = math.fabs((elev1 - elev2))
    if (delta < MIN_DELTA_Z):
        report_writeWarningMsg(L308, Link[j].ID)
        delta = MIN_DELTA_Z
    if (delta >= length):
        report_writeWarningMsg(L309, Link[j].ID)
        slope = _fdiv(delta, length)
    else:
        slope = _fdiv(delta, _sqrt(((((length) * (length))) - (((delta) * (delta))))))
    if ((MinSlope.v > 0.0) and (slope < MinSlope.v)):
        report_writeWarningMsg(L310, Link[j].ID)
        slope = MinSlope.v
        if ((RouteModel == SF) or (RouteModel == KW)):
            return slope
    if (elev1 < elev2):
        slope = -slope
    return slope


