def conduit_getLossRate(j, routeModel, q, tstep):
    xsect = None
    depth = (0.5 * ((Link[j].oldDepth + Link[j].newDepth)))
    length = 0.0
    width = 0.0
    topWidth = 0.0
    evapLossRate = 0.0
    seepLossRate = 0.0
    totalLossRate = 0.0
    if (depth > 0.0001):
        xsect = Link[j].xsect
        length = conduit_getLength(j)
        if ((xsect_isOpen(xsect.type_)) and (Evap.rate > 0.0)):
            topWidth = xsect_getWofY(xsect, depth)
            evapLossRate = ((topWidth * length) * Evap.rate)
        if (Link[j].seepRate > 0.0):
            if (xsect.type_ == RECT_CLOSED):
                width = xsect.wMax
            else:
                if (depth >= xsect.ywMax):
                    depth = xsect.ywMax
                width = xsect_getWofY(xsect, depth)
            seepLossRate = ((Link[j].seepRate * width) * length)
            seepLossRate *= Adjust.hydconFactor
        totalLossRate = (evapLossRate + seepLossRate)
        if (routeModel == DW):
            q = _fdiv(Link[j].newVolume, tstep)
        else:
            q = ((-(q) if (((q) < 0)) else (q)))
        if (totalLossRate > q):
            evapLossRate = _fdiv((evapLossRate * q), totalLossRate)
            seepLossRate = _fdiv((seepLossRate * q), totalLossRate)
            totalLossRate = q
    Conduit[Link[j].subIndex].evapLossRate = evapLossRate
    Conduit[Link[j].subIndex].seepLossRate = seepLossRate
    return totalLossRate


