def outlet_getInflow(j):
    k = 0
    n1 = 0
    n2 = 0
    head = 0.0
    hcrest = 0.0
    h1 = 0.0
    h2 = 0.0
    y1 = 0.0
    dir = 0.0
    n1 = Link[j].node1
    n2 = Link[j].node2
    k = Link[j].subIndex
    if (RouteModel == DW):
        h1 = (Node[n1].newDepth + Node[n1].invertElev)
        h2 = (Node[n2].newDepth + Node[n2].invertElev)
    else:
        h1 = (Node[n1].newDepth + Node[n1].invertElev)
        h2 = Node[n1].invertElev
    dir = (1.0 if ((h1 >= h2)) else -1.0)
    y1 = Node[n1].newDepth
    if (dir < 0.0):
        y1 = h1
        h1 = h2
        h2 = y1
        y1 = Node[n2].newDepth
    hcrest = (Node[n1].invertElev + Link[j].offset1)
    if ((Outlet[k].curveType == NODE_HEAD) and (RouteModel == DW)):
        head = (h1 - (((h2) if (((h2) >= (hcrest))) else (hcrest))))
    else:
        head = (h1 - hcrest)
    if (((head <= 0.0001) or (y1 <= 0.0001)) or (link_setFlapGate(j, n1, n2, dir))):
        Link[j].newDepth = 0.0
        Link[j].flowClass = DRY
        return 0.0
    Link[j].newDepth = head
    Link[j].flowClass = SUBCRITICAL
    return ((dir * Link[j].setting) * outlet_getFlow(k, head))


