def storage_getDepth(j, v):
    k = Node[j].subIndex
    i = Storage[k].aCurve
    shape = Storage[k].shape
    a0 = Storage[k].a0
    a1 = Storage[k].a1
    a2 = Storage[k].a2
    d = Box(0.0)
    e = 0.0
    storageVol = TStorageVol()
    if ((Node[j].fullVolume > 0.0) and (v >= Node[j].fullVolume)):
        return Node[j].fullDepth
    if (v == 0.0):
        return 0.0
    v *= (UCF(VOLUME))
    storageVol.k = k
    storageVol.v = v
    if shape == TABULAR:
        i = Storage[k].aCurve
        if (i >= 0):
            d.v = table_getStorageDepth(Curve[i], v)
        else:
            d.v = 0.0
    elif shape == CYLINDRICAL:
        d.v = _fdiv(v, a0)
    elif shape == PARABOLOID:
        d.v = _sqrt(_fdiv((2.0 * v), a1))
    elif shape == FUNCTIONAL:
        if (a2 == 0.0):
            d.v = _fdiv(v, ((a0 + a1)))
        elif (a0 == 0.0):
            e = _fdiv(1.0, ((a2 + 1.0)))
            d.v = _pow(_fdiv(v, ((a1 * e))), e)
        elif ((a2 == 1.0) and (a1 > 0.0)):
            d.v = _fdiv(((_sqrt(((a0 * a0) + ((2. * a1) * v))) - a0)), a1)
        else:
            d.v = _fdiv(v, ((a0 + a1)))
            findroot_Newton(0.0, (Node[j].fullDepth * UCF(LENGTH)), d, 0.001, storage_getVolDiff, storageVol)
    elif shape in (CONICAL, PYRAMIDAL):
        d.v = _fdiv(v, a0)
        findroot_Newton(0.0, (Node[j].fullDepth * UCF(LENGTH)), d, 0.001, storage_getVolDiff, storageVol)
    else:
        d.v = 0.0
    d.v = _fdiv(d.v, UCF(LENGTH))
    if (d.v > Node[j].fullDepth):
        d.v = Node[j].fullDepth
    return d.v


