def findNodeQual(j):
    p = 0
    qNode = 0.0
    qNode = Node[j].qualInflow
    if (qNode > 1e-10):
        p = 0
        while (p < Nobjects[POLLUT]):
            Node[j].newQual[p] = _fdiv(Node[j].newQual[p], qNode)
            p += 1
    else:
        p = 0
        while (p < Nobjects[POLLUT]):
            if (Node[j].newDepth > ZeroDepth):
                Node[j].newQual[p] = Node[j].oldQual[p]
            else:
                Node[j].newQual[p] = 0.0
            p += 1


# qualrout.c:253
def findLinkQual(i, tStep):
    j = 0
    k = 0
    p = 0
    wIn = 0.0
    qIn = 0.0
    qSeep = 0.0
    v1 = 0.0
    v2 = 0.0
    c1 = 0.0
    c2 = 0.0
    vEvap = 0.0
    vLosses = 0.0
    fEvap = 0.0
    barrels = 0.0
    j = Link[i].node1
    if (Link[i].newFlow < 0.0):
        j = Link[i].node2
    if ((Link[i].type_ != CONDUIT) or (Link[i].xsect.type_ == DUMMY)):
        p = 0
        while (p < Nobjects[POLLUT]):
            Link[i].newQual[p] = Node[j].newQual[p]
            p += 1
        return
    k = Link[i].subIndex
    barrels = Conduit[k].barrels
    qIn = (math.fabs(Conduit[k].q1) * barrels)
    qSeep = (Conduit[k].seepLossRate * barrels)
    vEvap = ((Conduit[k].evapLossRate * barrels) * tStep)
    v1 = Link[i].oldVolume
    v2 = Link[i].newVolume
    vLosses = ((qSeep * tStep) + vEvap)
    fEvap = 1.0
    if ((vEvap > 0.0) and (v1 > ZeroVolume)):
        fEvap += (_fdiv(vEvap, v1))
    if (RouteModel == SF):
        findSFLinkQual(i, qSeep, fEvap, tStep)
        return
    if (RouteModel == DW):
        qIn = (qIn + _fdiv((((v2 + vLosses) - v1)), tStep))
        qIn = (((qIn) if (((qIn) >= (0.0))) else (0.0)))
    p = 0
    while (p < Nobjects[POLLUT]):
        c1 = Link[i].oldQual[p]
        massbal_addSeepageLoss(p, (qSeep * c1))
        c1 *= fEvap
        c2 = getReactedQual(p, c1, v1, tStep)
        wIn = (Node[j].newQual[p] * qIn)
        c2 = getMixedQual(c2, v1, wIn, qIn, tStep)
        if ((v2 < ZeroVolume) or (Link[i].newDepth <= ZeroDepth)):
            massbal_addToFinalStorage(p, (c2 * v2))
            c2 = 0.0
        Link[i].newQual[p] = c2
        p += 1


# qualrout.c:357
def findSFLinkQual(i, qSeep, fEvap, tStep):
    j = Link[i].node1
    p = 0
    c1 = 0.0
    c2 = 0.0
    lossRate = 0.0
    p = 0
    while (p < Nobjects[POLLUT]):
        c1 = Node[j].newQual[p]
        massbal_addSeepageLoss(p, (qSeep * c1))
        c1 *= fEvap
        c2 = c1
        if (Pollut[p].kDecay > 0.0):
            c2 = (c1 * _exp((-Pollut[p].kDecay * tStep)))
