def findNWSOnlineFormat(f, line):
    global DataOffset, Interval, TimeOffset, ValueOffset
    n = 0
    fileFormat = UNKNOWN_FORMAT
    str_ = None
    rt.rewind(f)
    rt.fgets(line, 1024, f)
    if (((str_ := rt.strstr(line, L337))) != (None)):
        Interval = 3600
        TimeOffset = Interval
        ValueOffset = _i32((CPtr.diff(str_, line)))
        fileFormat = NWS_ONLINE_60
    elif (((str_ := rt.strstr(line, L338))) != (None)):
        Interval = 900
        TimeOffset = Interval
        ValueOffset = _i32((CPtr.diff(str_, line)))
        fileFormat = NWS_ONLINE_15
    else:
        return UNKNOWN_FORMAT
    n = 1
    while (n <= 5):
        if (rt.fgets(line, 1024, f) == (None)):
            return UNKNOWN_FORMAT
        if (rt.strstr(line, L334) == (None)):
            n += 1
            continue
        str_ = rt.strrchr(line, 58)
        if (str_ == (None)):
            return UNKNOWN_FORMAT
        n = _i32((CPtr.diff(str_, line)))
        DataOffset = (n - 11)
        return fileFormat
        n += 1
    return UNKNOWN_FORMAT


