    if (rainDepth > 0.0):
        netRainDepth = (rainDepth - ia)
        netRainDepth = (((netRainDepth) if (((netRainDepth) >= (0.0))) else (0.0)))
        ia = (rainDepth - netRainDepth)
        UHGroup[j].uh[k].iaUsed += ia
    else:
        UHGroup[j].uh[k].iaUsed -= ((dt / 86400.) * UnitHyd[j].iaRecov[m][k])
        UHGroup[j].uh[k].iaUsed = (((UHGroup[j].uh[k].iaUsed) if (((UHGroup[j].uh[k].iaUsed) >= (0.0))) else (0.0)))
        netRainDepth = 0.0
    return netRainDepth


