def updateDryPeriod(j, k, rainDepth, rainInterval):
    i = 0
    if (rainDepth > 0.0):
        if (UHGroup[j].uh[k].drySeconds >= (rainInterval * UHGroup[j].uh[k].maxPeriods)):
            i = 0
            while (i < UHGroup[j].uh[k].maxPeriods):
                UHGroup[j].uh[k].pastRain[i] = 0.0
