def report_readOptions(tok, ntoks):
    k = 0
    j = 0
    m = 0
    t = 0
    if (ntoks < 2):
        return error_setInpError(ERR_ITEMS, L0)
    k = findmatch(tok[0], ReportWords)
    if (k < 0):
        return error_setInpError(ERR_KEYWORD, tok[0])
    if ((k < 2) or (k > 4)):
        m = findmatch(tok[1], NoYesWords)
        if ((m < NO) or (m > YES)):
            return error_setInpError(ERR_KEYWORD, tok[1])
        if k == 0:
            RptFlags.disabled = m
            return 0
        elif k == 1:
            RptFlags.input_ = m
            return 0
        elif k == 5:
            RptFlags.continuity = m
            return 0
        elif k == 6:
            RptFlags.flowStats = m
            return 0
        elif k == 7:
            RptFlags.controls = m
            return 0
        elif k == 8:
            RptFlags.averages = m
            return 0
        elif k == 9:
            return 0
        else:
            return error_setInpError(ERR_KEYWORD, tok[1])
    else:
        if k == 2:
            m = SUBCATCH
        elif k == 3:
            m = NODE
        elif k == 4:
            m = LINK
    if strcomp(tok[1], L355):
        k = NONE
    elif strcomp(tok[1], L351):
        k = ALL
    else:
        k = SOME
        t = 1
        while (t < ntoks):
            j = project_findObject(m, tok[t])
            if (j < 0):
                return error_setInpError(ERR_NAME, tok[t])
            if m == SUBCATCH:
                Subcatch[j].rptFlag = 1
            elif m == NODE:
                Node[j].rptFlag = 1
            elif m == LINK:
                Link[j].rptFlag = 1
            t += 1
    if m == SUBCATCH:
        RptFlags.subcatchments = k
    elif m == NODE:
        RptFlags.nodes = k
    elif m == LINK:
        RptFlags.links = k
    return 0


