def report_RouteStepFreq(timeStepStats):
    totalSteps = 0.0
    i = 0
    i = 1
    while (i < 6):
        totalSteps += timeStepStats.timeStepCounts[i]
        i += 1
    if (totalSteps == 0):
        return
    rt.fprintf(Frpt.file, L493)
    i = 1
    while (i < 6):
        rt.fprintf(Frpt.file, L494, timeStepStats.timeStepIntervals[(i - 1)], timeStepStats.timeStepIntervals[i], _fdiv((100.0 * float((timeStepStats.timeStepCounts[i]))), totalSteps))
        i += 1


