def getY(x, table, n):
    i = 0
    x1 = 0.0
    y1 = 0.0
    dx = 0.0
    dy = 0.0
    if (x <= table[0][0]):
        return table[0][1]
    if (x >= (table[(n - 1)])[0]):
        return (table[(n - 1)])[1]
    i = 1
    while (i < n):
        if (x <= table[i][0]):
            x1 = (table[(i - 1)])[0]
            dx = (table[i][0] - x1)
            y1 = (table[(i - 1)])[1]
            dy = (table[i][1] - y1)
            return (y1 + _fdiv((((x - x1)) * dy), dx))
        i += 1
    return (table[(n - 1)])[1]


