def inflowHasChanged():
    j = 0
    diff = 0.0
    qOld = 0.0
    qNew = 0.0
    j = 0
    while (j < Nobjects[NODE]):
        qOld = Node[j].oldLatFlow
        qNew = Node[j].newLatFlow
        if (math.fabs(qOld) > 1e-06):
            diff = ((_fdiv(qNew, qOld)) - 1.0)
        elif (math.fabs(qNew) > 1e-06):
            diff = 1.0
        else:
            diff = 0.0
        if (math.fabs(diff) > LatFlowTol.v):
            return 1
        if ((Node[j].type_ == OUTFALL) or (Node[j].degree == 0)):
            qOld = Node[j].oldFlowInflow
            qNew = Node[j].inflow
            if (math.fabs(qOld) > 1e-06):
                diff = ((_fdiv(qNew, qOld)) - 1.0)
            elif (math.fabs(qNew) > 1e-06):
                diff = 1.0
            else:
                diff = 0.0
            if (math.fabs(diff) > LatFlowTol.v):
                return 1
        j += 1
    return 0


