# routing.c:929
def sortEvents():
    i = 0
    j = 0
    gap = 0
    temp = TEvent()
    gap = _idiv(NumEvents, 2)
    while (gap >= 1):
        i = gap
        while (i < NumEvents):
            temp = Event[i].clone()
            j = (i - gap)
            while ((j >= 0) and (Event[j].start > temp.start)):
                Event[(j + gap)] = Event[j].clone()
                j -= gap
            if (j != (i - gap)):
                Event[(j + gap)] = temp.clone()
            i += gap
        gap = _idiv(gap, 2)
    i = 0
    while (i < (NumEvents - 1)):
        if (Event[i].end > (Event[(i + 1)]).start):
            Event[i].end = (Event[(i + 1)]).start
        i += 1


