        swmm_start(1)
        if (not ErrorCode):
            writecon(L643)
            while True:
                swmm_step(elapsedTime)
                newHour = D2L(((elapsedTime.v * 24.0)))
                if (newHour > oldHour):
                    theDay = D2L(elapsedTime.v)
                    theHour = D2L(((((elapsedTime.v - _floor(elapsedTime.v))) * 24.0)))
                    writecon(L644)
                    rt.snprintf(Msg, (1024 & 0xFFFFFFFFFFFFFFFF), L645, theDay, theHour)
                    writecon(Msg)
