def swmm_step(elapsedTime):
    global ElapsedTime, ErrorCode
    elapsedTime.v = 0.0
    if ErrorCode:
        return ErrorCode
    if (not IsOpenFlag):
        return ((ErrorCode := ERR_API_NOT_OPEN))
    if (not IsStartedFlag):
        return ((ErrorCode := ERR_API_NOT_STARTED))
    if (NewRoutingTime < RoutingDuration):
        execRouting()
    if SaveResultsFlag:
        saveResults()
    if (NewRoutingTime < RoutingDuration):
        ElapsedTime = (NewRoutingTime / 86400000.0)
    else:
        ElapsedTime = 0.0
    elapsedTime.v = ElapsedTime
    return ErrorCode


