def swmm_stride(strideStep, elapsedTime):
    global ElapsedTime, ErrorCode, RouteStep, RoutingDuration
    realRouteStep = RouteStep
    elapsedTime.v = 0.0
    if ErrorCode:
        return ErrorCode
    if (not IsOpenFlag):
        return ((ErrorCode := ERR_API_NOT_OPEN))
    if (not IsStartedFlag):
        return ((ErrorCode := ERR_API_NOT_STARTED))
    RoutingDuration = (NewRoutingTime + (1000.0 * strideStep))
    RoutingDuration = (((TotalDuration) if (((TotalDuration) <= (RoutingDuration))) else (RoutingDuration)))
    if (strideStep < RouteStep):
        RouteStep = strideStep
    while True:
        swmm_step(elapsedTime)
        if not ((elapsedTime.v > 0.0) and (not ErrorCode)):
            break
    RouteStep = realRouteStep
    RoutingDuration = TotalDuration
    if (NewRoutingTime < TotalDuration):
        ElapsedTime = (NewRoutingTime / 86400000.0)
    else:
        ElapsedTime = 0.0
    elapsedTime.v = ElapsedTime
    return ErrorCode


