    if (NewRoutingTime >= ReportTime):
        if RptFlags.averages:
            if (NewRoutingTime == ReportTime):
                output_updateAvgResults()
            output_saveResults(ReportTime)
            if (NewRoutingTime > ReportTime):
                output_updateAvgResults()
        else:
            output_saveResults(ReportTime)
        ReportTime = (ReportTime + (1000 * float(ReportStep)))
    elif RptFlags.averages:
        output_updateAvgResults()


