# swmm5.c:982
def getSubcatchValue(property, index):
    subcatch = None
    if ((index < 0) or (index >= Nobjects[SUBCATCH])):
        return 0
    subcatch = Subcatch[index]
    if property == swmm_SUBCATCH_AREA:
        return (subcatch.area * UCF(LANDAREA))
    elif property == swmm_SUBCATCH_RAINGAGE:
        return subcatch.gage
    elif property == swmm_SUBCATCH_RAINFALL:
        if (subcatch.gage >= 0):
            return Gage[subcatch.gage].reportRainfall
        else:
            return 0.0
    elif property == swmm_SUBCATCH_EVAP:
        return (subcatch.evapLoss * UCF(EVAPRATE))
    elif property == swmm_SUBCATCH_INFIL:
        return (subcatch.infilLoss * UCF(RAINFALL))
    elif property == swmm_SUBCATCH_RUNOFF:
        return (subcatch.newRunoff * UCF(FLOW))
    elif property == swmm_SUBCATCH_RPTFLAG:
        return ((subcatch.rptFlag > 0))
    else:
        return 0


# swmm5.c:1019
def getNodeValue(property, index):
    node = None
    if ((index < 0) or (index >= Nobjects[NODE])):
        return 0
    node = Node[index]
    if property == swmm_NODE_TYPE:
        return node.type_
    elif property == swmm_NODE_ELEV:
        return (node.invertElev * UCF(LENGTH))
    elif property == swmm_NODE_MAXDEPTH:
        return (node.fullDepth * UCF(LENGTH))
    elif property == swmm_NODE_DEPTH:
        return (node.newDepth * UCF(LENGTH))
    elif property == swmm_NODE_HEAD:
        return (((node.newDepth + node.invertElev)) * UCF(LENGTH))
    elif property == swmm_NODE_VOLUME:
        return (node.newVolume * UCF(VOLUME))
    elif property == swmm_NODE_LATFLOW:
        return (node.newLatFlow * UCF(FLOW))
    elif property == swmm_NODE_INFLOW:
        return (node.inflow * UCF(FLOW))
    elif property == swmm_NODE_OVERFLOW:
        return (node.overflow * UCF(FLOW))
    elif property == swmm_NODE_RPTFLAG:
        return ((node.rptFlag > 0))
    else:
        return 0


# swmm5.c:1059
def getLinkValue(property, index):
    link = None
    if ((index < 0) or (index >= Nobjects[LINK])):
        return 0
    link = Link[index]
    if property == swmm_LINK_TYPE:
        return link.type_
    elif property == swmm_LINK_NODE1:
        return link.node1
    elif property == swmm_LINK_NODE2:
        return link.node2
    elif property == swmm_LINK_LENGTH:
        if (link.type_ == CONDUIT):
            return (Conduit[link.subIndex].length * UCF(LENGTH))
        else:
            return 0
    elif property == swmm_LINK_SLOPE:
        if (link.type_ == CONDUIT):
            return Conduit[link.subIndex].slope
        else:
            return 0
    elif property == swmm_LINK_FULLDEPTH:
        return (link.xsect.yFull * UCF(LENGTH))
    elif property == swmm_LINK_FULLFLOW:
        return (link.qFull * UCF(FLOW))
    elif property == swmm_LINK_FLOW:
        return ((link.newFlow * UCF(FLOW)) * float(link.direction))
    elif property == swmm_LINK_VELOCITY:
        return (link_getVelocity(index, math.fabs(link.newFlow), link.newDepth) * UCF(LENGTH))
    elif property == swmm_LINK_DEPTH:
        return (link.newDepth * UCF(LENGTH))
    elif property == swmm_LINK_TOPWIDTH:
        if (link.type_ == CONDUIT):
            return (xsect_getWofY(link.xsect, link.newDepth) * UCF(LENGTH))
        else:
            return 0
    elif property == swmm_LINK_SETTING:
        return link.setting
    elif property == swmm_LINK_TIMEOPEN:
        if (link.setting > 0.0):
            return (((getDateTime(NewRoutingTime) - link.timeLastSet)) * 24.)
        else:
            return 0
    elif property == swmm_LINK_TIMECLOSED:
        if (link.setting == 0.0):
            return (((getDateTime(NewRoutingTime) - link.timeLastSet)) * 24.)
        else:
            return 0
    elif property == swmm_LINK_RPTFLAG:
        return ((link.rptFlag > 0))
    else:
        return 0


