def topoSort(sortedLinks):
    global First, Last
    i = 0
    j = 0
    k = 0
    n = 0
    i1 = 0
    i2 = 0
    k1 = 0
    k2 = 0
    First = 0
    Last = -1
    i = 0
    while (i < Nobjects[NODE]):
        if (InDegree[i] == 0):
            Last += 1
            Stack[Last] = i
        i += 1
    n = 0
    while (First <= Last):
        i1 = Stack[First]
        k1 = StartPos[i1]
        k2 = (k1 + Node[i1].degree)
        k = k1
        while (k < k2):
            j = AdjList[k]
            sortedLinks[n] = j
            n += 1
            i2 = Link[j].node2
            InDegree[i2] -= 1
            if (InDegree[i2] == 0):
                Last += 1
                Stack[Last] = i2
            k += 1
        First += 1
    return n


