def lookup(x, table, nItems):
    delta = 0.0
    x0 = 0.0
    x1 = 0.0
    y = 0.0
    y2 = 0.0
    i = 0
    delta = _fdiv(1.0, ((float(nItems) - 1)))
    i = D2I((_fdiv(x, delta)))
    if (i >= (nItems - 1)):
        return table[(nItems - 1)]
    x0 = (i * delta)
    x1 = (((float(i) + 1)) * delta)
    y = (table[i] + _fdiv((((x - x0)) * ((table[(i + 1)] - table[i]))), delta))
    if (i < 2):
        y2 = (y + (_fdiv((((x - x0)) * ((x - x1))), ((delta * delta))) * ((((table[i] / 2.0) - table[(i + 1)]) + (table[(i + 2)] / 2.0)))))
        if (y2 > 0.0):
            y = y2
    if (y < 0.0):
        y = 0.0
    return y


