def invLookup(y, table, nItems):
    dx = 0.0
    x = 0.0
    x0 = 0.0
    dy = 0.0
    n = 0
    i = 0
    dx = _fdiv(1.0, ((float(nItems) - 1)))
    n = nItems
    if (table[(n - 3)] > table[(n - 1)]):
        n = (n - 2)
    if ((n < nItems) and (y > table[(nItems - 1)])):
        if (y >= table[(nItems - 3)]):
            return (((float(n) - 1)) * dx)
        if (y <= table[(nItems - 2)]):
            i = (nItems - 2)
        else:
            i = (nItems - 3)
    else:
        i = locate(y, table, (n - 1))
    if (i >= (n - 1)):
        return (((float(n) - 1)) * dx)
    x0 = (i * dx)
    dy = (table[(i + 1)] - table[i])
    if (dy == 0.0):
        x = x0
    else:
        x = (x0 + _fdiv((((y - table[i])) * dx), dy))
    if (x < 0.0):
        x = 0.0
    if (x > 1.0):
        x = 1.0
    return x


